<template><main class="quiz shell"><header class="quiz-head"><button class="icon-btn" aria-label="Volver" @click="back">←</button><span class="wordmark">DIANA <i>MATCH</i></span><span class="counter">{{index+1}} / 5</span></header><div class="progress"><span :style="{width:`${((index+1)/5)*100}%`}"/></div><div class="quiz-art" aria-hidden="true"><img src="../assets/spicy.png"/><img src="../assets/queso.png"/><img src="../assets/lemon.png"/><img src="../assets/fuego.png"/></div><section class="question"><p class="kicker">{{question.eyebrow||`PREGUNTA ${index+1} DE 5`}}</p><h1>{{question.title}}</h1><div class="options"><button v-for="option in question.options" :key="option.id" class="option" :class="{selected:answers[question.id]===option.id}" @click="choose(option.id)"><span class="option-emoji">{{option.emoji}}</span><span>{{option.label}}</span><span class="arrow">→</span></button></div><p class="hint">Elegí la que más se parezca a vos</p></section><div v-if="calculating" class="loading"><div class="spinner">🌶️</div><h2>{{loadingText}}</h2><p>Tu match está casi listo...</p></div></main></template>
<script setup lang="ts">
import { computed, ref } from 'vue'; import { useRouter } from 'vue-router'; import { questions } from '../data/quiz'; import { useExperience } from '../composables/useExperience'; import { trackEvent } from '../services/analytics'
const router=useRouter();const {answers,finish}=useExperience();const index=ref(Math.max(0,questions.findIndex(item=>!answers.value[item.id])));const calculating=ref(false);const loadingText=ref('ANALIZANDO TU ANTOJO...');const question=computed(()=>questions[index.value]);function back(){if(index.value>0)index.value-=1;else router.push('/')}function choose(id:string){answers.value[question.value.id]=id;trackEvent('question_answered',{question:question.value.id});if(index.value<4){setTimeout(()=>{index.value+=1},280);return}calculating.value=true;const lines=['ANALIZANDO TU ANTOJO...','Midiendo tu nivel de picante... 🌶️','Evaluando tus malas decisiones... 👀','Buscando tu Diana perfecto...'];let lineIndex=0;const timer=setInterval(()=>{lineIndex+=1;loadingText.value=lines[lineIndex]||lines[3];if(lineIndex>=3){clearInterval(timer);finish();setTimeout(()=>router.push('/result'),450)}},500)}
</script>
